CREATE OR REPLACE FUNCTION archive_old_annual_returns(cutoff_year bigint)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  -- Insert old records into archive
  INSERT INTO annual_returns_archive (yearlyid, portfolioref, calendaryear, fundperf, categoryperf)
  SELECT yearlyid, portfolioref, calendaryear, fundperf, categoryperf
  FROM annual_returns
  WHERE calendaryear < cutoff_year;

  -- Delete from main table after archiving
  DELETE FROM annual_returns
  WHERE calendaryear < cutoff_year;
END;
$$;

CREATE TABLE IF NOT EXISTS fund_style_change_log (
    log_id SERIAL PRIMARY KEY,
    fund_tickersym VARCHAR NOT NULL,
    old_risk jsonb NOT NULL,
    new_risk jsonb NOT NULL,
    change_timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE FUNCTION log_fund_style_change()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.risk3y IS DISTINCT FROM NEW.risk3y OR OLD.risk5y IS DISTINCT FROM NEW.risk5y OR OLD.risk10y IS DISTINCT FROM NEW.risk10y THEN
        INSERT INTO fund_style_change_log(fund_tickersym, old_risk, new_risk)
        VALUES (NEW.investmentref,
                jsonb_build_object('risk3y', OLD.risk3y, 'risk5y', OLD.risk5y, 'risk10y', OLD.risk10y),
                jsonb_build_object('risk3y', NEW.risk3y, 'risk5y', NEW.risk5y, 'risk10y', NEW.risk10y));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_log_risk_change ON risk_metrics;

CREATE TRIGGER trg_log_risk_change
AFTER UPDATE ON risk_metrics
FOR EACH ROW
EXECUTE FUNCTION log_fund_style_change();

SELECT tickersym, (fundmetrics->>'Yield_Rate')::float AS yield_rate
FROM funds
WHERE (fundmetrics->>'Yield_Rate')::float > 0.05;

SELECT tickersym, (fundmetrics->>'Net_Worth')::bigint AS net_worth
FROM funds
WHERE (fundmetrics->>'Net_Worth')::bigint BETWEEN 100000000 AND 1000000000;
